// WakeBack's one bit of native Android: joining a puck's setup WiFi ("wakeback-puck-N") from the app.
//
// The Android project itself is generated by `flutter create` (setup.ps1 / the APK workflow); this file is
// copied over the generated MainActivity.kt afterwards. Keep it tiny and dependency-free.
//
// Android 10+ won't let an app silently join a WiFi network, but it does let one ask for a *local-only*
// connection to a named network (WifiNetworkSpecifier): the system shows "Connect to device
// wakeback-puck-3?", the user taps Connect, the phone joins without dropping its mobile data, and we bind
// this app's sockets to that network so http://192.168.4.1 reaches the puck. `leave` unbinds and releases
// it (the phone drops back off the puck WiFi on its own).
//
// Dart side: lib/puck/puck_wifi.dart (MethodChannel "wakeback/puck_wifi": join(ssid|prefix) / leave() / hotspotSettings()).
// `join` with a `prefix` matches any "wakeback-puck-*": if several pucks are in setup mode the system dialog
// lists them and the user picks one.
package uk.bridgesolutions.wakeback

import android.content.Context
import android.content.Intent
import android.net.ConnectivityManager
import android.net.Network
import android.net.NetworkCapabilities
import android.net.NetworkRequest
import android.net.wifi.WifiNetworkSpecifier
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.os.PatternMatcher
import android.provider.Settings
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {
    private var callback: ConnectivityManager.NetworkCallback? = null

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "wakeback/puck_wifi").setMethodCallHandler { call, result ->
            when (call.method) {
                "supported" -> result.success(Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q)
                "join" -> join(call.argument<String>("ssid") ?: "", call.argument<String>("prefix") ?: "", result)
                "leave" -> { leave(); result.success(true) }
                "hotspotSettings" -> result.success(openHotspotSettings())
                else -> result.notImplemented()
            }
        }
    }

    private fun join(ssid: String, prefix: String, result: MethodChannel.Result) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
            result.error("unsupported", "Android 10 or newer is needed to join the puck from the app", null); return
        }
        if (ssid.isEmpty() && prefix.isEmpty()) { result.error("bad_ssid", "No network name", null); return }
        leave()
        val cm = getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager
        val sb = WifiNetworkSpecifier.Builder()                           // open network: the puck's setup WiFi has no password
        if (ssid.isNotEmpty()) sb.setSsid(ssid) else sb.setSsidPattern(PatternMatcher(prefix, PatternMatcher.PATTERN_PREFIX))
        val spec = sb.build()
        val name = if (ssid.isNotEmpty()) ssid else "$prefix…"
        val req = NetworkRequest.Builder()
            .addTransportType(NetworkCapabilities.TRANSPORT_WIFI)
            .removeCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
            .setNetworkSpecifier(spec)
            .build()
        var answered = false
        val main = Handler(Looper.getMainLooper())
        val cb = object : ConnectivityManager.NetworkCallback() {
            override fun onAvailable(network: Network) {
                cm.bindProcessToNetwork(network)
                if (!answered) { answered = true; main.post { result.success(true) } }
            }
            override fun onUnavailable() {
                if (!answered) { answered = true; main.post { result.error("unavailable", "Couldn't join $name", null) } }
                leave()
            }
            override fun onLost(network: Network) {
                cm.bindProcessToNetwork(null)
                if (!answered) { answered = true; main.post { result.error("lost", "Lost $name", null) } }
            }
        }
        callback = cb
        try {
            cm.requestNetwork(req, cb, 45_000)   // the system prompt waits for the user; give up after 45 s
        } catch (e: Exception) {
            callback = null
            if (!answered) { answered = true; result.error("error", e.message ?: "Couldn't ask for the network", null) }
        }
    }

    /** Android's hotspot (tethering) settings, so the user can turn the hotspot on after a puck is set up. */
    private fun openHotspotSettings(): Boolean {
        val tries = listOf(
            Intent().setClassName("com.android.settings", "com.android.settings.TetherSettings"),
            Intent(Settings.ACTION_WIRELESS_SETTINGS))
        for (i in tries) {
            try { startActivity(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)); return true } catch (_: Exception) {}
        }
        return false
    }

    private fun leave() {
        val cm = getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager
        try { cm.bindProcessToNetwork(null) } catch (_: Exception) {}
        callback?.let { try { cm.unregisterNetworkCallback(it) } catch (_: Exception) {} }
        callback = null
    }

    override fun onDestroy() {
        leave()
        super.onDestroy()
    }
}
